/**
 * Returns the frontmost application ignoring KeyForge itself, so a client can offer it when creating an auto-switch rule: while the user clicks a button in KeyForge, KeyForge is the app in front, so the useful answer is the last other app. The daemon keeps that app in memory and tracks it whether or not auto-switch is enabled. It may not be the app the user has in mind (e.g. the file manager KeyForge was opened from), so clients should let the user review it before saving a rule.
 */
export interface MethodGetFrontmostApp {
  /**
   * No parameters in v1.
   */
  params: {};
  result: {
    /**
     * OS-native application identifier, in the same format as AutoSwitchRule.app: bundle id on macOS, executable name on Linux/Windows. Absent when the daemon knows no app other than KeyForge, for example right after it started or when frontmost-app detection is unavailable on this system.
     */
    app?: string;
  };
}
